From c838b1dc344be138b32c8ca101c09bf7ddf08f69 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 05:04:38 +0100
Subject: [PATCH] inputmethod: start Plasma Keyboard for the lock screen when
 none is set

The lock screen's on-screen keyboard button did nothing unless an input
method was configured in the settings. When it asks for the keyboard
while locked, now start Plasma Keyboard and stop it again on unlock.

BUG: 527077
---
 src/inputmethod.cpp | 17 +++++++++++++++++
 src/inputmethod.h   |  6 ++++++
 2 files changed, 23 insertions(+)

diff --git a/src/inputmethod.cpp b/src/inputmethod.cpp
index ee7153b2db..2ec46ec47a 100644
--- a/src/inputmethod.cpp
+++ b/src/inputmethod.cpp
@@ -39,6 +39,7 @@
 // For v1 preedit styling enums
 #include "qwayland-server-text-input-unstable-v1.h"

+#include <KDesktopFile>
 #include <KLocalizedString>
 #include <KShell>

@@ -47,6 +48,7 @@
 #include <QDBusPendingCall>
 #include <QKeyEvent>
 #include <QMenu>
+#include <QStandardPaths>

 #include <fcntl.h>
 #include <linux/input-event-codes.h>
@@ -95,6 +97,11 @@ void InputMethod::init()
     });
 #if KWIN_BUILD_SCREENLOCKER
     connect(ScreenLocker::KSldApp::self(), &ScreenLocker::KSldApp::aboutToLock, this, &InputMethod::hide);
+    connect(ScreenLocker::KSldApp::self(), &ScreenLocker::KSldApp::unlocked, this, [this]() {
+        if (m_lockScreenInputMethod) {
+            setInputMethodCommand(QString());
+        }
+    });
 #endif

     new VirtualKeyboardDBus(this);
@@ -841,6 +848,7 @@ void InputMethod::setInputMethodCommand(const QString &command)
     }

     m_inputMethodCommand = command;
+    m_lockScreenInputMethod = false;

     startInputMethod();
     Q_EMIT availableChanged();
@@ -1007,6 +1015,15 @@ bool InputMethod::activeClientSupportsTextInput() const

 void InputMethod::forceActivate()
 {
+#if KWIN_BUILD_SCREENLOCKER
+    if (m_inputMethodCommand.isEmpty() && waylandServer()->isScreenLocked()) {
+        const QString desktopFile = QStandardPaths::locate(QStandardPaths::ApplicationsLocation, QStringLiteral("org.kde.plasma.keyboard.desktop"));
+        if (!desktopFile.isEmpty()) {
+            setInputMethodCommand(KDesktopFile(desktopFile).desktopGroup().readEntry("Exec", QString()));
+            m_lockScreenInputMethod = isAvailable();
+        }
+    }
+#endif
     setActive(true);
     m_forceShowRequested = true;
     if (m_panel) {
diff --git a/src/inputmethod.h b/src/inputmethod.h
index 8398e1477c..b6f3f20751 100644
--- a/src/inputmethod.h
+++ b/src/inputmethod.h
@@ -320,6 +320,12 @@ private:
      * of the input device that triggered the show request.
      */
     bool m_forceShowRequested = false;
+
+    /**
+     * Whether the input method was started by forceActivate() on the lock screen and should be
+     * stopped on unlock.
+     */
+    bool m_lockScreenInputMethod = false;
 };

 }
